pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalize creating "fragmented" small residuals (bins with < 20 space are hard to fill)
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - progress);
    }

    // Best-Fit Decreasing logic: Favor bins that result in a tight residual
    // We want to minimize the post_residual, but heavily penalize leaving a bin 
    // nearly empty if we have many bins already open.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base cost is high, but decreases as we run out of space
        score = 45.0 + (mean_residual * 0.5);
    } else {
        // If this is the only bin that fits the current item, prioritize it
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Lookahead: if the next item fits into the current post_residual, reward this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }

        // Global state: if we have many bins open, try to pack tighter into existing ones
        if open_bins_count > 5 {
            score += (open_bins_count as f64) * 0.5;
        }
    }

    // Dynamic pressure: towards the end of the stream, prioritize clearing residuals
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize leaving large gaps that are hard to fill.
    // We want post_residual to be as small as possible.

    // 2. Lookahead mechanism: If the next item fits perfectly into this post_residual, 
    // heavily reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_diff) * 2.5;
    }

    // 3. Prevent fragmentation: If this is the only bin that can fit the current item,
    // we should prioritize it unless the post_residual is extremely wasteful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. New Bin logic: Only open a new bin if the current mean_residual is already 
    // very tight (high utilization) or if we are forced to.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early in the stream unless necessary.
        score += 45.0 + (mean_residual * 0.5);
    }

    // 5. Global density optimization: Favor bins that stay closer to the current mean_residual.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 6. Progression scaling: As we approach the end of the stream, prioritize closing 
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tight (standard Best-Fit logic)
    // 2. New Bin Logic: If this is an empty bin (new bin candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no options or if the current options are very poor (fragmentation)
        // We add a threshold penalty based on the mean_residual of existing bins
        score = mean_residual * 0.85 + 25.0;
    } else {
        // 3. Lookahead Matching: Reward placing items that leave room for the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Perfect fit reward: If we can fit the next item exactly, heavily incentivize this bin
                score -= 40.0;
                // If the remainder after next_item_size is small, it's an even better fit
                let remainder = post_residual - next_item_size;
                score -= (10.0 - remainder as f64).max(0.0) * 2.0;
            } else {
                // If we cannot fit the next item, penalize if this bin had enough space to potentially fit it
                // but we "wasted" the capacity with the current item
                score += 15.0;
            }
        }

        // 4. Scarcity/Urgency: If this is the only bin that can fit the item, prioritize it
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // 5. Global Efficiency: Penalize opening too many bins as the stream progresses
        let progress = step_index as f64 / total_items as f64;
        score += (open_bins_count as f64) * progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
