    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual, which rewards tightness.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: scales with progress to favor consolidation early
    // and aggressive packing later.
    if is_new_bin {
        score += 25.0 * (1.0 + progress.powi(2));
    }

    // Lookahead logic: If the next item exists, penalize leaving a post_residual 
    // that is too small to accommodate the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Coupling: If we are near the end of the stream, prioritize smaller residuals 
    // more aggressively to close out bins.
    if post_residual < 10 {
        score -= (1.0 - progress) * 10.0;
    }

    // If this is the only bin that can fit the item, reduce its penalty 
    // to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Adjust based on the mean residual of the system to keep bin occupancy balanced.
    // If the current bin's post_residual is significantly better than the mean, favor it.
    score += (post_residual as f64 - mean_residual) * 0.5;

    score
}

