    // or if we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one can fit the item
            score += 40.0 + (mean_residual * 0.5);
        } else {
            // Baseline cost for opening a new bin when necessary
