pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    // We want to minimize remaining space (post_residual).
    let mut score = post;

    // Penalty for leaving a very small, unusable gap (fragmentation)
    // If post_residual is < 10, it is likely "dead space".
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is less than next_item_size, we penalize the bin.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Dynamic constraint: As the stream progresses, increase the cost of opening new bins.
    // If this is an empty bin (bin_residual == bin_capacity), apply a progressive barrier.
    if bin_residual == bin_capacity {
        // The barrier grows as the stream progresses, making it harder to open new bins late.
        // We add a penalty proportional to the current open_bins_count to encourage consolidation.
        score += 20.0 + (progress * 40.0) + (open_bins_count as f64 * 2.0);
    } else {
        // If this is an existing bin, reward it if it's closer to the mean_residual
        // to keep usage density uniform across bins.
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // Final adjustment: if this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}
